import { markdownDocumentHistoryStore$ } from './markdown_document_history_cell'
import { MarkdownDocumentHistoryMonitor } from './markdown_document_history_monitor'

/** Registers the card-scoped history store with MDXEditor's root Lexical editor. */
export function MarkdownDocumentHistoryPlugin() {
    const historyStore = useCellValue(markdownDocumentHistoryStore$)
    const [editor] = useLexicalComposerContext()
    const historyStoreError = historyStore ? null : new Error('Cannot register Markdown history without a history store')
    useDialogError(historyStoreError, 'Markdown history is unavailable')

    useEffect(() => {
        if (!historyStore) return

        const unregister = historyStore.registerEditorHistory(editor)

        return () => {
            unregister()
            historyStore.detachEditor(editor)
        }
    }, [editor, historyStore])

    return historyStore ? <MarkdownDocumentHistoryMonitor /> : null
}

import { addComposerChild$, realmPlugin, rootEditor$ } from '@mdxeditor/editor'
import {
    markdownDocumentHistoryConfig$,
    markdownDocumentHistoryStore$,
    type MarkdownDocumentHistoryConfig,
} from './markdown_document_history_cell'
import { MarkdownDocumentHistoryPlugin } from './markdown_document_history_plugin'

/** Connects a document identity and its history store to an MDXEditor realm. */
export const markdownDocumentHistoryPlugin = realmPlugin<MarkdownDocumentHistoryConfig>({
    init(realm, params) {
        if (!params) throw new Error('Markdown document history plugin requires parameters')

        realm.register(markdownDocumentHistoryConfig$)
        realm.register(markdownDocumentHistoryStore$)
        realm.pub(markdownDocumentHistoryConfig$, params)
        realm.pub(markdownDocumentHistoryStore$, params.historyStore)
        realm.pub(addComposerChild$, MarkdownDocumentHistoryPlugin)
    },
    postInit(realm, params) {
        if (!params) throw new Error('Markdown document history plugin requires parameters')

        const editor = realm.getValue(rootEditor$)
        if (!editor) throw new Error('Cannot initialize Markdown document history without an editor')

        const target = params.dataSource.getActiveTarget(params.binding)
        const markdown = target ? params.dataSource.getMarkdown(target) : ''
        params.historyStore.attachEditor(editor, target, markdown)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown document history plugin requires parameters')

        realm.pub(markdownDocumentHistoryConfig$, params)
    },
})

